import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { AlertsButton } from '@/components/AlertsButton'
import { EvidenceDrawer, type DrawerView } from '@/components/EvidenceDrawer'
import { Plan } from '@/components/Plan'
import { Routines, RoutinesLive } from '@/components/Routines'
import { pendingOf, refreshNow, suggestionFor, useLive } from '@/components/routines/live'
import { MapLegend, SupplierList, SupplyMap, type MapSelection } from '@/components/SupplyMap'
import { Today, type DoneInfo } from '@/components/Today'
import { TopBar, type Page } from '@/components/TopBar'
import { DECIDED, DONE_WORD, fetchState, tidy, viaOf, type Card, type State } from '@/lib/api'
import { actionIdOf } from '@/lib/decisions'
import { lookAlikes, repeatWords, todayOrder, trucksLeave } from '@/lib/today'

const POLL_MS = 5000

function useMedia(q: string) {
  const [on, setOn] = useState(() => window.matchMedia(q).matches)
  useEffect(() => {
    const m = window.matchMedia(q)
    const f = () => setOn(m.matches)
    m.addEventListener('change', f)
    return () => m.removeEventListener('change', f)
  }, [q])
  return on
}

export default function App() {
  const [state, setState] = useState<State | null>(null)
  const [error, setError] = useState(false)
  const [nowMs, setNowMs] = useState(Date.now())
  const [path, setPath] = useState(window.location.pathname)
  const [search, setSearch] = useState(window.location.search)
  const [toast, setToast] = useState<string | null>(null)
  const [pulseNode, setPulseNode] = useState<string | null>(null)
  const [drafts, setDrafts] = useState(0)
  // Today: the decision in focus, and the "Done" screen after one.
  const [focusId, setFocusId] = useState<string | null>(null)
  const [done, setDone] = useState<DoneInfo | null>(null)
  const decidedHere = useRef(new Set<string>())
  const [mapSel, setMapSel] = useState<MapSelection>({})
  const [drawer, setDrawer] = useState<DrawerView>(null)
  const seenEvents = useRef<Set<string> | null>(null)
  const lastStatus = useRef<Map<string, string> | null>(null)
  const offset = useRef(0)
  const phone = !useMedia('(min-width: 1024px)')
  const narrow = useMedia('(max-width: 767px)')
  // Opened from a push alert (/d/<id>?talk=1): the card rings as an incoming call.
  const [ringing, setRinging] = useState(new URLSearchParams(window.location.search).get('talk') === '1')
  const stopRinging = () => {
    setRinging(false)
    window.history.replaceState(null, '', window.location.pathname)
  }
  const go = useCallback((to: string) => {
    window.history.pushState(null, '', to)
    setPath(window.location.pathname)
    setSearch(window.location.search)
    window.scrollTo(0, 0)
  }, [])

  const live = useLive()
  const pending = pendingOf(live).length + drafts

  const load = useCallback(async () => {
    try {
      const s = await fetchState()
      offset.current = new Date(s.now).getTime() - Date.now()
      setNowMs(Date.now() + offset.current)
      setState(s)
      setError(false)

      // A new portal drop: say the agents are reading it (and pulse its place on the map).
      const ev = new Set(s.events.map((e) => e.id))
      if (seenEvents.current) {
        const added = s.events.filter((e) => !seenEvents.current!.has(e.id))
        if (added.length) {
          const e = added[0]
          const name = (e.path || e.file || '').split('/').pop()
          setToast(`New file: ${name}. Your agents are reading it.`)
          setPulseNode(e.node ?? null)
          window.setTimeout(() => setToast(null), 5000)
          window.setTimeout(() => setPulseNode(null), 4500)
        }
      }
      seenEvents.current = ev

      // Decided elsewhere (on a call): show "Done" for it too, unless a routine did it.
      const prev = lastStatus.current
      if (prev) {
        const c = s.cards.find((x) => prev.get(x.id) === 'open' && DECIDED.includes(x.status) && !decidedHere.current.has(x.id))
        const acts = c ? s.activity.filter((a) => a.card === c.id) : []
        if (c && !acts.some((a) => viaOf(a)?.kind === 'routine')) {
          const a = acts.find((x) => viaOf(x)?.kind === 'voice') ?? acts[0]
          decidedHere.current.add(c.id)
          void finish(s, {
            card: c,
            text: a ? stop(tidy(a.text)) : `${DONE_WORD[c.status] ?? 'Done'}.`,
            sub: viaOf(a ?? { text: '', kind: '' })?.kind === 'voice' ? 'Decided on the call.' : 'Decided elsewhere.',
            actionId: actionIdOf(a),
          })
        }
      }
      lastStatus.current = new Map(s.cards.map((c) => [c.id, c.status]))
    } catch {
      setError(true)
    }
  }, [])

  async function finish(s: State, d: { card: Card; text: string; sub: string; actionId: string | null }) {
    const k = Date.now()
    const more = lookAlikes(d.card, s).length
    if (more > 0) {
      setDone({ ...d, offer: (await hasRoutine(d.card.id)) ? 0 : more, k })
      return
    }
    // Show Done at once; a repeat offer follows when the server counts this decision as a repeat.
    setDone({ ...d, offer: 0, k })
    await refreshNow()
    const sg = suggestionFor(d.card.id)
    if (!sg || sg.count < 2) return
    const repeat = { n: sg.count, words: repeatWords(sg.decision, sg.action, d.card) }
    setDone((cur) => (cur && cur.k === k ? { ...cur, repeat } : cur))
  }

  useEffect(() => {
    void load()
    const poll = window.setInterval(load, POLL_MS)
    const tick = window.setInterval(() => setNowMs(Date.now() + offset.current), 15000)
    const nav = () => { setPath(window.location.pathname); setSearch(window.location.search) }
    window.addEventListener('popstate', nav)
    return () => { clearInterval(poll); clearInterval(tick); window.removeEventListener('popstate', nav) }
  }, [load])

  // Voice drafts waiting in Routines count towards "Your routines want to do N things".
  useEffect(() => {
    const get = async () => {
      try {
        const r = await fetch('/api/routines/drafts')
        if (r.ok) setDrafts(((await r.json()).drafts ?? []).filter((x: { routine?: { id?: string } }) => x?.routine?.id).length)
      } catch { /* optional */ }
    }
    void get()
    const t = window.setInterval(get, 30000)
    return () => clearInterval(t)
  }, [])

  const today = useMemo(() => (state ? todayOrder(state) : []), [state])
  // Plan opens a case on Today, with a quiet way back.
  const openCase = useCallback((id: string) => {
    setDone(null)
    go(`/d/${encodeURIComponent(id)}?from=plan`)
  }, [go])

  // Old links (/plan?card=<id>) now open the case on Today.
  const oldCard = path.startsWith('/plan') ? new URLSearchParams(search).get('card') : null
  useEffect(() => {
    if (oldCard) window.history.replaceState(null, '', `/d/${encodeURIComponent(oldCard)}?from=plan`)
    if (oldCard) { setPath(window.location.pathname); setSearch(window.location.search) }
  }, [oldCard])

  if (!state) {
    return <div className="grid h-full place-items-center text-[15px] text-ink-3">{error ? 'Cannot reach the server.' : 'Loading…'}</div>
  }

  const single = path.match(/^\/d\/(.+)$/)
  const page: Page | null = single || path === '/' ? 'today' : path.startsWith('/plan') ? 'plan' : path.startsWith('/suppliers') ? 'suppliers' : path.startsWith('/routines') ? 'routines' : 'today'
  // Routines is its own page; "Show me how" lands there drafting from the decision.
  const openRoutines = (request?: { cardId: string; k: number }) =>
    go(request ? `/routines?draft=${encodeURIComponent(request.cardId)}` : '/routines')
  const truck = trucksLeave(state, nowMs)
  const open = today.length
  const status = (
    <>
      {truck && <span className="font-medium text-ink">{truck}</span>}
      {truck && (open > 0 || !phone || done) && ' · '}
      {phone && open > 0 ? (
        page === 'today'
          ? <button className="cursor-pointer hover:text-ink" onClick={() => go('/plan')}>{open} {open === 1 ? 'decision' : 'decisions'}</button>
          : `${open} ${open === 1 ? 'decision' : 'decisions'}`
      ) : done && open === 0 ? 'nothing else due' : open > 0 ? `${open} ${open === 1 ? 'decision needs' : 'decisions need'} you` : phone ? null : 'nothing needs you'}
    </>
  )
  const bar = (
    <TopBar
      page={page}
      go={go}
      onRoutines={() => openRoutines()}
      status={status}
      bell={<AlertsButton />}
      phone={phone}
      routinesBadge={pending}
    />
  )
  const routines = <RoutinesLive state={state} />
  const overlays = (
    <>
      {toast && (
        <div className="toast-in t-small fixed left-1/2 top-[76px] z-50 -translate-x-1/2 rounded-full bg-ink px-4 py-2 text-white shadow-lg" role="status">
          {toast}
        </div>
      )}
      <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
      {routines}
    </>
  )

  // ------------------------------------------------------------ Today (/ and /d/<id>)
  if (page === 'today') {
    const pinned = single ? state.cards.find((c) => c.id === decodeURIComponent(single[1])) ?? null : null
    const pinnedOpen = pinned && pinned.status !== 'open' ? null : pinned
    // A case opened by link that is no longer open is shown as it stands (unless just decided here).
    const caseCard = pinned && !pinnedOpen && done?.card.id !== pinned.id ? pinned : null
    const card = single
      ? pinnedOpen ?? (done ? null : today[0] ?? null)
      : today.find((c) => c.id === focusId) ?? today[0] ?? null
    const fromPlan = !!single && new URLSearchParams(search).get('from') === 'plan'
    return (
      <div className="flex min-h-full flex-col bg-ground">
        {bar}
        <Today
          state={state}
          nowMs={nowMs}
          phone={phone}
          card={card}
          order={today}
          onFocus={(id) => { setFocusId(id); if (single) go('/') }}
          done={done}
          onDone={(d) => { decidedHere.current.add(d.card.id); void finish(state, d) }}
          onClearDone={() => { setDone(null); if (single) go('/') }}
          onChanged={load}
          onRoutines={openRoutines}
          go={go}
          ringing={ringing && !!pinnedOpen && card?.id === pinnedOpen.id}
          onRingingDone={stopRinging}
          pending={pending}
          caseCard={caseCard}
          onBack={fromPlan ? () => go('/plan') : null}
          onDrawer={(c, tab) => setDrawer({ card: c, tab })}
        />
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ Routines
  if (page === 'routines') {
    return (
      <div className="flex min-h-full flex-col bg-ground">
        {bar}
        <Routines state={state} onChanged={load} phone={narrow} />
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ Suppliers
  if (page === 'suppliers') {
    const list = (
      <SupplierList state={state} nowMs={nowMs} selection={mapSel} onSelect={setMapSel} onOpen={(id) => go(`/d/${encodeURIComponent(id)}`)} />
    )
    if (narrow) {
      return (
        <div className="flex min-h-full flex-col bg-ground">
          {bar}
          <div className="relative h-[300px] shrink-0">
            <SupplyMap state={state} hoverRoutes={[]} selection={mapSel} onSelect={setMapSel} pulseNode={pulseNode} />
          </div>
          <MapLegend className="px-6 pt-3" />
          <div className="px-6 pb-16 pt-8">{list}</div>
          {overlays}
        </div>
      )
    }
    return (
      <div className="flex h-full flex-col bg-ground">
        {bar}
        <div className="flex min-h-0 flex-1">
          <div className="flex min-w-0 flex-1 flex-col pb-6 pl-6">
            <div className="relative min-h-[420px] flex-1">
              <SupplyMap state={state} hoverRoutes={[]} selection={mapSel} onSelect={setMapSel} pulseNode={pulseNode} />
            </div>
            <MapLegend className="pt-3" />
          </div>
          <aside className="scroll-thin w-[380px] shrink-0 overflow-y-auto px-10 pb-16 pt-6 xl:w-[420px]" aria-label="Suppliers">{list}</aside>
        </div>
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ Plan: the overview, no decisions
  return (
    <div className="flex min-h-full flex-col bg-ground">
      {bar}
      <Plan state={state} nowMs={nowMs} phone={narrow} onOpen={openCase} onChanged={load} />
      {overlays}
    </div>
  )
}

const stop = (t: string) => (/[.!?]$/.test(t) ? t : `${t}.`)

// A routine already written from this card: do not offer to automate it again.
async function hasRoutine(cardId: string): Promise<boolean> {
  try {
    const r = await fetch('/api/routines')
    if (!r.ok) return false
    const { routines } = (await r.json()) as { routines: { created_from?: string }[] }
    return routines.some((x) => x.created_from === cardId)
  } catch {
    return false
  }
}

import { useEffect, useMemo, useState, type ReactNode } from 'react'
import { LaunchTimeline } from '@/components/LaunchTimeline'
import { DONE_WORD, ago, fmtNum, tidy, type Card, type State } from '@/lib/api'
import { actionIdOf, sameIssueOn, sections, when, type Group, type Handled } from '@/lib/decisions'
import { shortName, shortTitle } from '@/lib/today'
import { cn } from '@/lib/utils'
import { UndoAction } from './routines/Undo'

// Plan: the overview. The launch timeline, then every case in four quiet groups. Nothing is
// decided here: a row (or a timeline marker) opens the case on Today, where decisions happen.

interface Props {
  state: State
  nowMs: number
  phone: boolean
  /** Opens a case on Today (/d/<id>?from=plan). */
  onOpen: (cardId: string) => void
  onChanged: () => void
}

const DONE_SHOWN = 6
const first = (s?: string) => (!s ? '' : /\s[a-z]/.test(s) ? s : (s.split(' ').find((w) => !w.endsWith('.')) ?? s))
const typing = (t: EventTarget | null) =>
  t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))
/** A focused row or button answers Enter itself. */
const pressable = (t: EventTarget | null) =>
  t instanceof HTMLElement && (/^(BUTTON|A)$/.test(t.tagName) || t.getAttribute('role') === 'button')

export function Plan({ state, nowMs, phone, onOpen, onChanged }: Props) {
  const sec = useMemo(() => sections(state), [state])
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [expanded, setExpanded] = useState<Set<string>>(new Set())
  const [allDone, setAllDone] = useState(false)
  const done = allDone ? sec.done : sec.done.slice(0, DONE_SHOWN)
  const needN = sec.needs.reduce((n, g) => n + g.cards.length, 0)
  const suppliers = new Set(state.shipments.map((s) => s.supplier_id)).size

  // The order j / k walks: one id per visible row.
  const order = useMemo(() => [
    ...sec.needs.flatMap((g) => (expanded.has(g.key) ? g.cards.map((c) => c.id) : [g.lead.id])),
    ...sec.waiting.map((c) => c.id),
    ...sec.handled.flatMap((h) => (h.card ? [h.card.id] : [])),
    ...done.map((c) => c.id),
  ], [sec, expanded, done])

  // Desk keyboard: j / k (or arrows) move the selection, Enter opens it on Today.
  useEffect(() => {
    if (phone) return
    const onKey = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey || typing(e.target)) return
      const k = e.key
      if (k === 'Enter') {
        if (selectedId && !pressable(e.target)) { e.preventDefault(); onOpen(selectedId) }
        return
      }
      const down = k === 'j' || k === 'J' || k === 'ArrowDown'
      const up = k === 'k' || k === 'K' || k === 'ArrowUp'
      if (!down && !up) return
      e.preventDefault()
      const i = selectedId ? order.indexOf(selectedId) : -1
      const n = i < 0 ? 0 : Math.min(order.length - 1, Math.max(0, i + (down ? 1 : -1)))
      const id = order[n]
      if (!id) return
      setSelectedId(id)
      document.getElementById(`row-${id}`)?.scrollIntoView({ block: 'nearest' })
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [phone, order, selectedId, onOpen])

  // Arriving at /plan#handled (from All clear's "undo"): bring that group into view.
  useEffect(() => {
    const id = window.location.hash.slice(1)
    if (id) document.getElementById(id)?.scrollIntoView({ block: 'start' })
  }, [])

  const toggle = (key: string) =>
    setExpanded((e) => { const n = new Set(e); if (n.has(key)) n.delete(key); else n.add(key); return n })
  const row = { state, nowMs, phone, selectedId, onOpen }

  return (
    <div className="flex-1">
      <div className={cn('border-b border-hair', phone ? 'px-6 pb-2 pt-2' : 'px-8 pb-4 xl:px-12')}>
        <LaunchTimeline state={state} nowMs={nowMs} selectedId={selectedId} onSelect={onOpen} compact={phone} />
      </div>

      <div className={cn('mx-auto w-full max-w-[880px] space-y-12', phone ? 'px-3 pb-24 pt-8' : 'px-8 pb-32 pt-14')}>
        <Section title="Needs you" n={needN}>
          {sec.needs.length ? (
            sec.needs.map((g) => <GroupRows key={g.key} g={g} open={expanded.has(g.key)} onToggle={() => toggle(g.key)} {...row} />)
          ) : (
            <li className="t-small px-3.5 text-ink-2">Nothing needs you right now.</li>
          )}
        </Section>

        {sec.waiting.length > 0 && (
          <Section title="Waiting on others" n={sec.waiting.length}>
            {sec.waiting.map((c) => (
              <Row
                key={c.id}
                card={c}
                {...row}
                dot="hollow"
                who={shortName(c.supplier_name) || c.part_name || ''}
                at={c.ui?.at ? `since ${when(c.ui.at, nowMs)}` : ''}
                status={`${c.status === 'escalated' ? 'Waiting for' : 'With'} ${first(c.approver) || 'the approver'}`}
              />
            ))}
          </Section>
        )}

        {sec.handled.length > 0 && (
          <Section id="handled" title="Handled for you" n={sec.handled.length} routine>
            {sec.handled.map((h) => <HandledRow key={h.key} h={h} {...row} onChanged={onChanged} />)}
          </Section>
        )}

        {sec.done.length > 0 && (
          <Section title="Decided by you" n={sec.done.length}>
            {done.map((c) => {
              const a = state.activity.find((x) => x.card === c.id)
              // A sent email cannot be taken back, so no Undo for it.
              const undo = c.status !== 'sent' ? actionIdOf(a) : null
              return (
                <Row
                  key={c.id}
                  card={c}
                  {...row}
                  dot="quiet"
                  who={shortName(c.supplier_name) || c.part_name || ''}
                  at={c.ui?.at ? when(c.ui.at, nowMs) : ''}
                  status={DONE_WORD[c.status] ?? 'Done'}
                  undo={undo ? <UndoAction actionId={undo} onUndone={onChanged} /> : null}
                />
              )
            })}
            {sec.done.length > DONE_SHOWN && (
              <li className="px-3.5 pt-2">
                <button onClick={() => setAllDone(!allDone)} className="t-small cursor-pointer text-ink-3 hover:text-ink">
                  <span className="border-b border-hair">{allDone ? 'Show fewer' : `Show all ${sec.done.length}`}</span>
                </button>
              </li>
            )}
          </Section>
        )}

        <div className="t-small space-y-2 px-3.5 text-ink-3">
          <p>
            Watching {state.shipments.length} shipments from {suppliers} suppliers and every new portal file
            {state.read_since_6 > 0 ? ` (${state.read_since_6} read since 06:00)` : ''}. Last check {ago(state.last_check_at, nowMs)}.
          </p>
          {!phone && <p><kbd>J</kbd> <kbd>K</kbd> to move, <kbd>Enter</kbd> to open it in Today</p>}
        </div>
      </div>
    </div>
  )
}

function Section({ id, title, n, routine, children }: { id?: string; title: string; n: number; routine?: boolean; children: ReactNode }) {
  return (
    <section id={id} className="scroll-mt-6">
      <h2 className={cn('t-small px-3.5', routine ? 'dot-routine text-routine' : 'text-ink-3')}>{title} · {n}</h2>
      <ul className="mt-3">{children}</ul>
    </section>
  )
}

type RowBase = { state: State; nowMs: number; phone: boolean; selectedId: string | null; onOpen: (id: string) => void }

const rowCls =
  't-small grid w-full cursor-pointer items-baseline gap-x-3.5 rounded-[10px] px-3.5 py-3 text-left hover:bg-soft/70 focus-visible:outline-2 focus-visible:outline-accent'

/**
 * One case: dot, headline, who and when underneath, where it stands in words on the right (on a
 * phone, at the end of the line underneath). A div with role=button: it may hold an Undo button.
 */
function Row({
  card, state, phone, selectedId, onOpen, dot, who, at, status, late, extra, undo, title, routine,
}: RowBase & {
  card: Card
  dot: 'open' | 'late' | 'hollow' | 'routine' | 'quiet'
  who: ReactNode
  at: string
  status: string
  late?: boolean
  extra?: ReactNode
  undo?: ReactNode
  title?: string
  /** The who part is a routine's name: green. */
  routine?: boolean
}) {
  const on = selectedId === card.id
  const quiet = dot === 'quiet' || dot === 'hollow' || dot === 'routine'
  const statusEl = <span className={cn(late ? 'text-late' : 'text-ink-3')}>{status}</span>
  const sep = <span aria-hidden="true">·</span>
  return (
    <li>
      <div
        role="button"
        tabIndex={0}
        id={`row-${card.id}`}
        onClick={() => onOpen(card.id)}
        onKeyDown={(e) => { if (e.key === 'Enter' && e.target === e.currentTarget) { e.preventDefault(); onOpen(card.id) } }}
        aria-current={on ? 'true' : undefined}
        className={cn(rowCls, phone ? 'grid-cols-[8px_minmax(0,1fr)]' : 'grid-cols-[8px_minmax(0,1fr)_auto]', on && 'bg-soft')}
      >
        <i
          aria-hidden="true"
          className={cn(
            'h-[7px] w-[7px] -translate-y-px rounded-full',
            on ? 'bg-accent'
              : dot === 'late' ? 'bg-late'
              : dot === 'open' ? 'bg-ink'
              : dot === 'routine' ? 'bg-routine'
              : 'bg-ground ring-1 ring-ink-3/50',
          )}
        />
        <span className="min-w-0">
          <span className={cn('line-clamp-2', on ? 'font-medium text-ink' : quiet ? 'text-ink-2' : 'text-ink')}>
            {title ?? shortTitle(card, state)}
          </span>
          <span className="mt-0.5 flex min-w-0 flex-wrap items-center gap-x-2 text-ink-3">
            {who && <span className={cn('truncate', routine && 'text-routine')}>{who}</span>}
            {who && at && sep}
            {at && <span>{at}</span>}
            {phone && status !== 'Your call' && <>{(who || at) && sep}{statusEl}</>}
            {extra}
            {phone && undo && <>{sep}{undo}</>}
          </span>
        </span>
        {!phone && (
          <span className="flex items-baseline justify-end gap-2 text-right">
            {statusEl}
            {undo && <><span aria-hidden="true" className="text-ink-3">·</span>{undo}</>}
          </span>
        )}
      </div>
    </li>
  )
}

function GroupRows(p: RowBase & { g: Group; open: boolean; onToggle: () => void }) {
  const { g, nowMs } = p
  const lead = g.lead
  const late = lead.level === 'red'
  const decideBy = (c: Card) =>
    c.deadline ? (new Date(c.deadline).getTime() <= nowMs ? 'decide now' : `decide by ${when(c.deadline, nowMs)}`) : ''
  const toggle = g.cards.length > 1 && (
    <>
      <span aria-hidden="true">·</span>
      <button
        onClick={(e) => { e.stopPropagation(); p.onToggle() }}
        onKeyDown={(e) => e.stopPropagation()}
        aria-expanded={p.open}
        className="cursor-pointer text-ink-3 underline decoration-hair underline-offset-4 hover:text-ink"
      >
        {p.open ? 'hide' : `${g.cards.length - 1} more like this`}
      </button>
    </>
  )
  return (
    <>
      <Row
        card={lead}
        {...p}
        dot={late ? 'late' : 'open'}
        who={shortName(lead.supplier_name) || lead.part_name || ''}
        at={decideBy(lead)}
        status={late ? 'Misses the trucks' : 'Your call'}
        late={late}
        extra={toggle}
      />
      {p.open && g.cards.slice(1).map((c) => {
        const label = sameIssueOn({ ...g, cards: [g.lead, c] }) ?? tidy(c.headline)
        const on = p.selectedId === c.id
        return (
          <li key={c.id}>
            <button
              id={`row-${c.id}`}
              onClick={() => p.onOpen(c.id)}
              aria-current={on ? 'true' : undefined}
              className={cn(rowCls, 'flex items-baseline justify-between gap-3 py-2 pl-[38px]', on && 'bg-soft')}
            >
              <span className={cn('truncate', on ? 'font-medium text-ink' : 'text-ink-2')}>Same issue on {label}</span>
              <span className="shrink-0 text-ink-3">{c.number != null && c.number > 0 ? fmtNum(c.number) : decideBy(c)}</span>
            </button>
          </li>
        )
      })}
    </>
  )
}

function HandledRow(p: RowBase & { h: Handled; onChanged: () => void }) {
  const { h, nowMs } = p
  const status = (h.status && DONE_WORD[h.status]) || 'Done'
  const undo = h.actionId && h.status !== 'sent' ? <UndoAction actionId={h.actionId} onUndone={p.onChanged} /> : null
  const who = h.routine ? `‘${h.routine}’` : 'A routine'
  if (h.card) {
    return (
      <Row
        card={h.card}
        {...p}
        dot="routine"
        title={shortTitle(h.card, p.state)}
        who={who}
        routine
        at={h.at ? when(h.at, nowMs) : ''}
        status={status}
        undo={undo}
      />
    )
  }
  // Routine work without a case on screen: shown, not opened.
  return (
    <li>
      <div className={cn(rowCls, 'cursor-default hover:bg-transparent', p.phone ? 'grid-cols-[8px_minmax(0,1fr)]' : 'grid-cols-[8px_minmax(0,1fr)_auto]')}>
        <i aria-hidden="true" className="h-[7px] w-[7px] -translate-y-px rounded-full bg-routine" />
        <span className="min-w-0">
          <span className="line-clamp-2 text-ink-2">{tidy(h.text)}</span>
          <span className="mt-0.5 flex min-w-0 flex-wrap items-center gap-x-2 text-ink-3">
            <span className="truncate text-routine">{who}</span>
            {h.at && <><span aria-hidden="true">·</span><span>{when(h.at, nowMs)}</span></>}
            {p.phone && undo && <><span aria-hidden="true">·</span>{undo}</>}
          </span>
        </span>
        {!p.phone && <span className="flex justify-end">{undo}</span>}
      </div>
    </li>
  )
}

