// What the Today screen says, derived from /api/state: which decision comes first, a short
// headline, the contradiction as one sentence, what it means for today's packing, and the
// recommendation. Nothing here knows a specific supplier, part or number.

import { DECIDED, costText, fmtDay, fmtTime, sentence, tidy, viaOf, type Card, type Evidence, type State } from '@/lib/api'
import { byUrgency, groupKey, launchAt, mismatchPair, sourceName, span } from '@/lib/decisions'

const ms = (iso?: string | null) => (iso ? new Date(iso).getTime() : NaN)

/** Open decisions for the viewer, most urgent first: the server's inbox order, then urgency. */
export function todayOrder(state: State): Card[] {
  const open = state.cards.filter((c) => c.status === 'open' && !c.routed_to_other)
  const rank = new Map(state.inbox_ids.map((id, i) => [id, i]))
  return open.sort((a, b) => {
    const ra = rank.get(a.id) ?? Infinity, rb = rank.get(b.id) ?? Infinity
    return ra !== rb ? ra - rb : byUrgency(a, b)
  })
}

/** "Trucks leave in 13 h 30 min"; null without a launch time. */
export function trucksLeave(state: State, nowMs: number): string | null {
  const at = launchAt(state)
  if (!at) return null
  const left = ms(at) - nowMs
  return left > 0 ? `Trucks leave in ${span(left)}` : 'The trucks have left'
}

export const plural = (n: number, one: string, many = `${one}s`) => `${n.toLocaleString('en-GB')} ${n === 1 ? one : many}`

// ---------------------------------------------------------------- words

/** "Game Card 128 GB" -> "game cards"; quoted names keep their case. */
export function noun(partName: string | null | undefined, many = true): string {
  if (!partName) return many ? 'parts' : 'part'
  if (partName.includes('"')) {
    const [head, ...rest] = partName.split(' ')
    return [head.toLowerCase() + (many && !head.endsWith('s') ? 's' : ''), ...rest].join(' ')
  }
  const words = partName.split(/\s+/)
  while (words.length > 1 && /^(\d+[\w.]*|[A-Z]{2,}|[–-])$/.test(words[words.length - 1])) words.pop()
  const out = words.map((w) => (/^[A-Z][a-z]+$/.test(w) ? w.toLowerCase() : w))
  const last = out.length - 1
  if (many && !/s$/i.test(out[last])) out[last] += 's'
  return out.join(' ')
}

const PARENS = /\s*\([^)]*\)/g
/** Text without the part's long product name: "Art Book Grand Heist 6 (96 p, hardcover)" -> "art books". */
export function plain(text: string | null | undefined, partName?: string | null): string {
  let t = tidy(text).replace(PARENS, '')
  if (partName) {
    const base = partName.replace(PARENS, '').trim()
    const i = t.indexOf(base)
    if (i >= 0) {
      const after = t.slice(i + base.length)
      // A run of capitalised words and numbers right after the name is the product title.
      const tail = after.match(/^(?:\s*[–-]\s*|\s+)(?:[A-Z][A-Za-z]*|\d+)(?:\s+(?:[A-Z][A-Za-z]*|\d+))*(?=[\s,.:;]|$)/)
      const before = t.slice(0, i)
      const counted = /\d\s*$/.test(before) && !/(^|\D)1\s*$/.test(before)
      const n = noun(partName, counted)
      t = before + (i === 0 ? n[0].toUpperCase() + n.slice(1) : n) + after.slice(tail ? tail[0].length : 0)
    }
  }
  return t.replace(/\s+([,.:;])/g, '$1').replace(/\s{2,}/g, ' ').trim()
}

const firstSentence = (t: string) => {
  const m = t.match(/^.*?[.!?](?=\s+[A-Z0-9]|$)/)
  return (m ? m[0] : t).trim()
}
const stop = (t: string) => (/[.!?]$/.test(t) ? t : `${t}.`)
const cap = (t: string) => (t ? t[0].toUpperCase() + t.slice(1) : t)

/** True when the goods a card is about arrive after the trucks leave. */
export function afterLaunch(card: Card, state: State): boolean {
  const l = launchAt(state)
  return !!(card.arrives_at && l && ms(card.arrives_at) > ms(l))
}

/** The big headline: plain words, one sentence, no part codes. */
export function headlineOf(card: Card, state: State): string {
  const h = plain(card.headline, card.part_name)
  if (afterLaunch(card, state)) {
    const n = tidy(card.headline).match(/\d[\d,.]*\d|\d/)?.[0]
    if (n) return `${n} ${noun(card.part_name, n !== '1')} will arrive after launch.`
  }
  // Drop a trailing ", but ..." clause on long headlines; the sentence below says it.
  const one = firstSentence(h).replace(/\s+on PO \d{6,}/g, '')
  const short = one.length > 70 ? one.replace(/,\s+(but|which|while)\b.*$/, '') : one
  return stop(cap(short))
}

/** One line for a list: shorter still. */
export function shortTitle(card: Card, state: State): string {
  return headlineOf(card, state)
    .replace(/\bwill arrive after launch\b/, 'arrive late')
    .replace(/^We have /, '')
    .replace(/\.$/, '')
}

/** "PackRight" from "Guangzhou PackRight", "Hwaseong" from "Hwaseong Memory". */
export function shortName(name?: string | null): string {
  if (!name) return ''
  const words = name.split(/\s+/)
  return words.find((w) => /^[A-Z][a-z]+[A-Z]/.test(w)) ?? words[0]
}

// ---------------------------------------------------------------- the contradiction

export interface Side {
// What the main screen derives from /api/state: the inbox sections, near-identical cards grouped
// into one row, the one-sentence launch verdict and the countdown to the trucks. Nothing here
// knows about a specific supplier, part or number: it all comes from the cards and the strip.

import {
  DECIDED, LEVEL_RANK, fmtDay, fmtNum, fmtTime, tidy, viaOf, type ActivityItem, type Card, type State, type StripItem,
} from '@/lib/api'

/** Several cards with the same problem (same supplier, same headline once numbers are removed). */
export interface Group {
  key: string
  cards: Card[]
  /** The card shown for the group: the most urgent one. */
  lead: Card
}

const shape = (t: string) => tidy(t).replace(/\d[\d,.' ]*\d|\d/g, '#').replace(/\s+/g, ' ').trim().toLowerCase()
export const groupKey = (c: Card) => `${c.supplier_id ?? c.supplier_name ?? ''}|${c.kind ?? ''}|${shape(c.headline)}`

const deadlineMs = (c: Card) => (c.deadline ? new Date(c.deadline).getTime() : Number.POSITIVE_INFINITY)
/** Most urgent first: earliest decide-by time, then the worse level, then the bigger number. */
export const byUrgency = (a: Card, b: Card) =>
  deadlineMs(a) - deadlineMs(b) || LEVEL_RANK[b.level] - LEVEL_RANK[a.level] || (b.number ?? 0) - (a.number ?? 0)

export function groupCards(cards: Card[]): Group[] {
  const map = new Map<string, Card[]>()
  for (const c of [...cards].sort(byUrgency)) {
    const k = groupKey(c)
    map.set(k, [...(map.get(k) ?? []), c])
  }
  return [...map.entries()].map(([key, cs]) => ({ key, cards: cs, lead: cs[0] }))
}

/** "PO 4500318774, 4500318765 and 4500318786": what differs between the cards of a group. */
export function sameIssueOn(g: Group): string | null {
  if (g.cards.length < 2) return null
  const first = tidy(g.lead.headline)
  const firstTokens = new Set(first.match(/\d[\d,.]*\d|\d/g) ?? [])
  const lead = [...firstTokens].find((t) => t.replace(/\D/g, '').length >= 4) ?? [...firstTokens][0]
  // The word in front of the lead's own number ("PO") names what the others are.
  const word = lead ? first.slice(0, first.indexOf(lead)).trim().split(/\s+/).pop() : undefined
  const others = g.cards.slice(1).map((c) => {
    const toks = tidy(c.headline).match(/\d[\d,.]*\d|\d/g) ?? []
    return toks.find((t) => !firstTokens.has(t)) ?? tidy(c.headline)
  })
  const list = others.length > 1 ? `${others.slice(0, -1).join(', ')} and ${others[others.length - 1]}` : others[0]
  return word && /^[A-Za-z]{1,12}$/.test(word) ? `${word} ${list}` : list
}

export const routineOf = (state: State, cardId: string): string | null => {
  const a = state.activity.find((x) => x.card === cardId && viaOf(x)?.kind === 'routine')
  const v = a ? viaOf(a) : null
  return v?.kind === 'routine' ? v.name : null
}

/** The action a routine took, for undo; null when the item carries no action id. */
export const actionIdOf = (a?: ActivityItem | null): string | null => (a ? a.action_id || a.id || null : null)
export const routineActionOf = (state: State, cardId: string): string | null =>
  actionIdOf(state.activity.find((x) => x.card === cardId && viaOf(x)?.kind === 'routine'))

const fmtLong = (iso: string) => {
  const d = new Date(/^\d{4}-\d{2}-\d{2}$/.test(iso) ? `${iso}T12:00:00Z` : iso)
  return Number.isNaN(d.getTime())
    ? tidy(iso)
    : new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Europe/Berlin' }).format(d)
}

/** "Hwaseong confirms 20,000 on Tue 24 Nov", plus whether that date misses the launch. */
export function replyFacts(card: Card): { text: string; late: boolean } | null {
  const u = card.ui ?? {}
  const qty = u.reply_quantity
  if (!u.reply_date && (qty == null || qty === '')) return null
  const who = u.reply_from || card.supplier_name || 'The supplier'
  const n = typeof qty === 'number' ? fmtNum(qty) : qty ? tidy(String(qty)) : ''
  const what = n ? `${n}${card.part_name ? ` ${card.part_name}` : ''}` : 'delivery'
  return { text: `${who} confirms ${what}${u.reply_date ? ` on ${fmtLong(u.reply_date)}` : ''}`, late: u.reply_after_launch === true }
}

export interface Handled {
  key: string
  card?: Card
  text: string
  at?: string
  routine: string | null
  status?: string
  /** Set when the routine's action can be undone. */
  actionId?: string | null
}

export interface Sections {
  needs: Group[]
  waiting: Card[]
  /** Decided by a routine (and routine actions without a card). */
  handled: Handled[]
  /** Decided by a person. */
  done: Card[]
}

